import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        last_login TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT,
        action TEXT,
        details TEXT
    )''')
    # seed admin
    admin_hash = hashlib.sha256(b'admin_secret_2024').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, api_key) VALUES (?, ?, ?, ?)",
               ('admin', admin_hash, 'admin', 'ak_admin_7f3b2c'))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports filtering."""
    query_param = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Validate field against allowed columns
    allowed_fields = ['username', 'role', 'last_login', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above, q is user input
    sql = f"SELECT id, username, role, last_login FROM users WHERE {field} LIKE '%{query_param}%'"

    try:
        db = get_db()
        results = db.execute(sql).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        # Log error for debugging
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/profile', methods=['GET'])
def get_profile():
    """Get user profile by API key"""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    user = db.execute("SELECT id, username, role, last_login FROM users WHERE api_key = ?", 
                      (api_key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    return jsonify(dict(user))

@app.route('/api/audit', methods=['GET'])
def get_audit_log():
    """Retrieve audit log entries"""
    limit = request.args.get('limit', '50')
    try:
        limit = min(int(limit), 200)
    except ValueError:
        limit = 50

    db = get_db()
    logs = db.execute("SELECT * FROM audit_log ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
    return jsonify({'logs': [dict(row) for row in logs]})

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    os.makedirs('/var/lib/app', exist_ok=True)
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
